	if params.Limit != nil {
		q.Add("limit", queryParam(*params.Limit))
	}
	if params.Anchor != nil {
		q.Add("anchor", *params.Anchor)
	}
	if params.Direction != nil {
		q.Add("direction", *params.Direction)
	}
	if params.BeforeLimit != nil {
		q.Add("before_limit", queryParam(*params.BeforeLimit))
	}
	if params.AfterLimit != nil {
		q.Add("after_limit", queryParam(*params.AfterLimit))
	}
	if params.IncludeAnchor != nil {
		q.Add("include_anchor", queryParam(*params.IncludeAnchor))
	}
	if params.AnchorAgentMode != nil {
		q.Add("anchor_agent_mode", *params.AnchorAgentMode)
	}
	if params.AnchorAgent != nil {
		q.Add("anchor_agent", *params.AnchorAgent)
	}
	if params.IncludeReplyCounts != nil {
		q.Add("include_reply_counts", queryParam(*params.IncludeReplyCounts))
	}
	return fetch[*ThreadMessagesResponse](r.http, ctx, requestSpec{Method: "GET", Path: "/api/v1/threads/" + url.PathEscape(thread) + "/messages", Query: q})
